import { createMiddleware } from '@tanstack/react-start'
import { supabase } from './client'

// Must be registered as a global `functionMiddleware` in `src/start.ts`; otherwise
// the browser never attaches the bearer token to serverFn RPCs.
export const attachSupabaseAuth = createMiddleware({ type: 'function' }).client(
  async ({ next }) => {
    // getSession() recovers session from storage (classic SPA) or cookies (SSR)
    // If it fails or is null, no Authorization header is sent, which is correct for public server functions.
    // serverFn handlers using .middleware([requireSupabaseAuth]) will catch missing headers.
    let session = null;
    try {
      const { data } = await supabase.auth.getSession();
      session = data.session;
      
      // Se não houver token mas existir um usuário (sessão persistida mas sem token em memória)
      // ou se o token estiver visivelmente expirado, tenta refresh silencioso.
      if (!session?.access_token) {
        const { data: userData } = await supabase.auth.getUser();
        if (userData.user) {
          console.log("[AUTH_ATTACHER] Token ausente mas usuário existe. Tentando refresh...");
          const { data: refreshData, error: rErr } = await supabase.auth.refreshSession();
          if (rErr) {
            console.error("[AUTH_ATTACHER] Refresh falhou:", rErr);
            // IMPORTANTE: Se o refresh falhar por DNS/Rede (TypeError: Failed to fetch), 
            // precisamos logar isso claramente para diferenciar de erro de credencial.
            if (rErr.message === 'Failed to fetch') {
              console.error("[AUTH_ATTACHER] ERRO DE REDE/DNS: O cliente não conseguiu alcançar o servidor de autenticação.");
            }
          }
          session = refreshData.session;
        }
      }
    } catch (e) {
      console.error("[AUTH_ATTACHER] Erro crítico ao recuperar sessão:", e);
    }

    const token = session?.access_token;
    return next({
      headers: token ? { Authorization: `Bearer ${token}` } : {},
    });
  },
);
